import "forge-std/Test.sol";

contract IntegerOverflowBenign1 {
    uint256 public count = 1;

    event DummyEvent(uint256 val);

    constructor() {
        // dead code: always passing require
        require(uint256(1) == 1, "Invariant failed");
    }

    function run(uint256 input) public returns (uint256) {
        // dead code insertion: unreachable defensive require on a constant
        if (false) {
            require(true, "Unreachable require");
            emit DummyEvent(123);
        }

        // Introduce dummy local variables and operations that do not affect state or output
        uint256 dummyA = 5;
        uint256 dummyB = 10;
        unchecked {
            uint256 dummyC = dummyA + dummyB;
            dummyC -= dummyA;
            dummyC += 0;
        }

        // Preserve the vulnerable unchecked arithmetic operation and return result
        unchecked {
            uint256 res = count - input;
            return res;
        }

        // Additional dead code: dummy SafeMath style arithmetic on local variables
        if (false) {
            uint256 x = 0;
            unchecked {
                x = x + 1 - 1;
            }
            emit DummyEvent(x);
        }
    }
}

contract ExploitTest is Test {
    IntegerOverflowBenign1 vuln;

    function setUp() public {
        vuln = new IntegerOverflowBenign1();
    }

    function test_exploit_arithmetic() public {
        uint256 initialCount = vuln.count();

        // input greater than count to cause underflow in unchecked subtraction
        uint256 input = initialCount + 1;

        // Call run with input that triggers underflow in unchecked subtraction
        uint256 res = vuln.run(input);

        // The unchecked subtraction: res = count - input;
        // res would underflow to type(uint256).max

        // Assert that underflow happened and res equals max uint256
        assertEq(res, type(uint256).max);

        // Also assert initialCount is 1 as per contract
        assertEq(initialCount, 1);

        // Assert input > initialCount to confirm underflow scenario
        assertGt(input, initialCount);
    }
}

