import "forge-std/Test.sol";

contract SmartBillions {
    address public owner;
    uint public investStart;
    mapping(address => uint) public balanceOf;
    mapping(address => Bet) public bets;

    struct Bet {
        uint blockNum;
        uint32 betHash;
    }

    constructor() {
        owner = msg.sender;
        investStart = block.number + 1000;
    }

    function setInvestStart(uint _start) external {
        require(msg.sender == owner, "Only owner");
        investStart = _start;
    }

    function resetBet() external {
        require(msg.sender == owner, "Only owner");
        // Reset bets mapping is omitted for simplicity
    }

    function investDirect() external payable {
        require(block.number >= investStart, "Investing not started");
        balanceOf[msg.sender] += msg.value / 1e15; // PLAY tokens with decimals=0
    }

    receive() external payable {
        if (block.number >= investStart) {
            play();
        }
    }

    function play() public payable {
        require(balanceOf[msg.sender] > 0, "No PLAY tokens");

        // Use bad randomness: betHash is truncated blockhash of current block
        uint32 betHash = uint32(uint256(blockhash(block.number)) & 0xFFFFFF);

        bets[msg.sender] = Bet(block.number, betHash);
    }

    function betOf(address player) public view returns (uint) {
        Bet memory b = bets[player];
        if (b.blockNum == 0) return 0;

        bytes32 bh = blockhash(b.blockNum);
        if (bh == bytes32(0)) return 0;

        uint24 betHash24 = uint24(b.betHash);
        uint24 blockHash24 = uint24(uint256(bh) & 0xFFFFFF);
        uint24 hit = betHash24 ^ blockHash24;

        uint matches = 0;
        for (uint i = 0; i < 6; i++) {
            if (((hit >> (4 * i)) & 0xF) == 0) {
                matches++;
            }
        }

        uint betAmount = balanceOf[player];
        uint prize;

        if (matches == 6) {
            prize = betAmount * 7_000_000;
        } else if (matches == 5) {
            prize = betAmount * 20_000;
        } else if (matches == 4) {
            prize = betAmount * 500;
        } else if (matches == 3) {
            prize = betAmount * 25;
        } else if (matches == 2) {
            prize = betAmount * 3;
        } else {
            prize = 0;
        }

        return prize;
    }

    function disinvest() external {
        uint prize = betOf(msg.sender);
        require(prize > 0, "No prize");

        // Reset bet and balance
        bets[msg.sender] = Bet(0, 0);
        balanceOf[msg.sender] = 0;

        // Send prize in ETH
        (bool sent, ) = payable(msg.sender).call{value: prize * 1e15}("");
        require(sent, "Transfer failed");
    }
}

