pragma solidity ^0.8.20;

import "forge-std/Test.sol";

contract Vulnerable {
    event CallAttempt(address target, bool success);

    // Function that calls target with empty calldata via low-level call and does NOT check return value
    function callTarget(address target) external {
        (bool success, ) = target.call("");
        // Unchecked success, no revert on failure
        emit CallAttempt(target, success);
    }
}

contract Rejecter {
    fallback() external payable {
        revert("Rejecting fallback");
    }
}

contract UncheckedLowLevelCallsExploitTest is Test {
    Vulnerable public vulnerable;
    Rejecter public rejecter;

    function setUp() public {
        vulnerable = new Vulnerable();
        rejecter = new Rejecter();
    }

    function test_exploit_unchecked_low_level_calls() public {
        // Expect event with success == false because Rejecter fallback reverts
        vm.expectEmit(true, true, true, true);
        emit Vulnerable.CallAttempt(address(rejecter), false);

        // This call would normally revert if .call() result was checked, but vulnerable contract ignores it
        vulnerable.callTarget(address(rejecter));

        // Additionally, test that calling a normal address returns true success
        address normalTarget = address(this);
        vm.expectEmit(true, true, true, true);
        emit Vulnerable.CallAttempt(normalTarget, true);
        vulnerable.callTarget(normalTarget);

        // We can assert here that the rejecter's fallback reverts by calling directly (expect revert)
        vm.expectRevert(bytes("Rejecting fallback"));
        (bool success, ) = address(rejecter).call("");
        assertTrue(!success);

        // But the vulnerable contract call does not revert, so test passes if we reach here
        // The key exploit: vulnerable.callTarget did NOT revert despite inner revert
        // and emitted event with success == false proving unchecked low-level call vulnerability
        assertTrue(true);
    }
}

