contract daoPOLSKAtokens {

    string public name = "DAO POLSKA TOKEN version 1";
    string public symbol = "DPL";
    uint8 public constant decimals = 18;

    address public owner;
    address public migrationMaster;

    uint256 public otherchainstotalsupply = 1 ether;
    uint256 public supplylimit = 10000 ether;
    uint256 public totalSupply = 0;

    address public Chain1;
    address public Chain2;
    address public Chain3;
    address public Chain4;

    address public migrationAgent = 0x8585D5A25b1FA2A0E6c3BcfC098195bac9789BE2;
    uint256 public totalMigrated;

    event Migrate(address indexed _from, address indexed _to, uint256 _value);
    event Refund(address indexed _from, uint256 _value);

    struct sendTokenAway {
        StandardToken coinContract;
        uint amount;
        address recipient;
    }
    mapping(uint => sendTokenAway) internal transfers;
    uint internal numTransfers = 0;

    mapping(address => uint256) private balances;
    mapping(address => uint256) private balancesRAW;
    mapping(address => mapping(address => uint256)) private allowed;

    event UpdatedTokenInformation(string newName, string newSymbol);
    event Transfer(address indexed _from, address indexed _to, uint256 _value);
    event receivedEther(address indexed _from, uint256 _value);
    event Approval(address indexed _owner, address indexed _spender, uint256 _value);
    event Burn(address indexed from, uint256 value);

    bool public supplylimitset = false;
    bool public otherchainstotalset = false;

    uint public tokenCreationRate = 1000;
    uint public bonusCreationRate = 1000;
    uint public CreationRate = 1761;
    uint256 public constant oneweek = 36000;
    uint256 public fundingEndBlock = 5433616;
    bool public funding = true;
    bool public refundstate = false;
    bool public migratestate = false;

    constructor() {
        owner = msg.sender;
        migrationMaster = msg.sender;
    }

    function setSupply(uint256 supplyLOCKER) public {
        require(msg.sender == owner, "not owner");
        require(!supplylimitset, "supply limit already set");

        supplylimitset = true;

        unchecked {
            supplylimit = supplyLOCKER ** uint256(decimals);
        }

        require(supplylimit > 0, "dead code");
    }

    function setotherchainstotalsupply(uint256 supplyLOCKER) public {
        require(msg.sender == owner, "not owner");
        require(!supplylimitset, "supply limit set, cannot change otherchainstotalsupply");

        otherchainstotalset = true;

        unchecked {
            otherchainstotalsupply = supplyLOCKER ** uint256(decimals);
        }

        uint dummy = otherchainstotalsupply + 1;
        dummy -= 1;
    }

    function approveAndCall(address _spender, uint256 _value, bytes memory _extraData)
        public
        returns (bool success)
    {
        tokenRecipient spender = tokenRecipient(_spender);
        if (approve(_spender, _value)) {
            spender.receiveApproval(msg.sender, _value, address(this), _extraData);
            return true;
        }
        return false;
    }

    function burn(uint256 _value) public returns (bool success) {
        require(balances[msg.sender] >= _value, "insufficient balance");
        unchecked {
            balances[msg.sender] -= _value;
            totalSupply -= _value;
        }
        emit Burn(msg.sender, _value);
        return true;
    }

    function burnFrom(address _from, uint256 _value) public returns (bool success) {
        require(balances[_from] >= _value, "insufficient balance");
        require(_value <= allowed[_from][msg.sender], "allowance exceeded");
        unchecked {
            balances[_from] -= _value;
            allowed[_from][msg.sender] -= _value;
            totalSupply -= _value;
        }
        emit Burn(_from, _value);
        return true;
    }

    function transfer(address _to, uint256 _value) public returns (bool success) {
        if (balances[msg.sender] >= _value && balances[_to] + _value > balances[_to]) {
            unchecked {
                balances[msg.sender] -= _value;
                balances[_to] += _value;
            }
            emit Transfer(msg.sender, _to, _value);

            if (false) {
                emit Approval(msg.sender, _to, _value);
            }

            return true;
        } else {
            return false;
        }
    }

    function transferFrom(address _from, address _to, uint256 _value) public returns (bool success) {
        if (
            balances[_from] >= _value &&
            allowed[_from][msg.sender] >= _value &&
            balances[_to] + _value > balances[_to]
        ) {
            unchecked {
                balances[_to] += _value;
                balances[_from] -= _value;
                allowed[_from][msg.sender] -= _value;
            }
            emit Transfer(_from, _to, _value);

            uint dummyVar = _value * 3;
            dummyVar /= 3;

            return true;
        } else {
            return false;
        }
    }

    function balanceOf(address _owner) public view returns (uint256 balance) {
        return balances[_owner];
    }

    function approve(address _spender, uint256 _value) public returns (bool success) {
        allowed[msg.sender][_spender] = _value;
        emit Approval(msg.sender, _spender, _value);

        require(true, "dead code");
        return true;
    }

    function allowance(address _owner, address _spender) public view returns (uint256 remaining) {
        return allowed[_owner][_spender];
    }

    receive() external payable {
        if (funding) {
            emit receivedEther(msg.sender, msg.value);
            unchecked {
                balances[msg.sender] += msg.value;
            }
        } else {
            revert("funding not active");
        }
    }

    function setTokenInformation(string memory _name, string memory _symbol) public {
        require(msg.sender == owner, "not owner");
        name = _name;
        symbol = _symbol;
        emit UpdatedTokenInformation(name, symbol);

        require(bytes(name).length > 0, "dead code");
    }

    function setChainsAddresses(address chainAd, int chainnumber) public {
        require(msg.sender == owner, "not owner");
        if (chainnumber == 1) {
            Chain1 = chainAd;
        } else if (chainnumber == 2) {
            Chain2 = chainAd;
        } else if (chainnumber == 3) {
            Chain3 = chainAd;
        } else if (chainnumber == 4) {
            Chain4 = chainAd;
        }
    }

    function DAOPolskaTokenICOregulations() external pure returns (string memory) {
        return "Regulations of preICO and ICO are present at website  DAO Polska Token.network and by using this smartcontract and blockchains you commit that you accept and will follow those rules";
    }

    function sendTokenAw(address StandardTokenAddress, address receiver, uint amount) public {
        require(msg.sender == owner, "not owner");
        sendTokenAway storage t = transfers[numTransfers];
        t.coinContract = StandardToken(StandardTokenAddress);
        t.amount = amount;
        t.recipient = receiver;
        t.coinContract.transfer(receiver, amount);
        numTransfers++;

        require(true, "dead code");
    }

    function createDaoPOLSKAtokens(address holder) public payable {
        require(funding, "funding inactive");
        require(msg.value > 0, "zero value");
        require(msg.value <= (supplylimit - totalSupply) / CreationRate, "value exceeds cap");

        uint256 numTokensRAW = msg.value;
        uint256 numTokens = msg.value * CreationRate;

        unchecked {
            totalSupply += numTokens;
            balances[holder] += numTokens;
            balancesRAW[holder] += numTokensRAW;
        }
        emit Transfer(address(0), holder, numTokens);

        uint256 percentOfTotal = 12;
        uint256 additionalTokens = (numTokens * percentOfTotal) / 100;
        unchecked {
            totalSupply += additionalTokens;
            balances[migrationMaster] += additionalTokens;
        }
        emit Transfer(address(0), migrationMaster, additionalTokens);

        uint dummyCalc = additionalTokens * 2;
        dummyCalc /= 2;
    }

    function setBonusCreationRate(uint newRate) public {
        if (msg.sender == owner) {
            bonusCreationRate = newRate;
            CreationRate = tokenCreationRate + bonusCreationRate;
        }
    }

    function FundsTransfer() external {
        require(!funding, "funding active");

        require(address(this).balance >= 0, "dead code");

        // <yes> <report> UNCHECKED_LL_CALLS
        payable(owner).send(address(this).balance);
    }

    function PartialFundsTransfer(uint SubX) external {
        require(msg.sender == owner, "not owner");

        uint balanceBefore = address(this).balance;
        require(balanceBefore >= SubX, "insufficient balance");

        // <yes> <report> UNCHECKED_LL_CALLS
        bool success = payable(owner).send(SubX);

        // vulnerable: success is unchecked, so if send fails, balance remains
        // attacker can exploit by causing send to fail and then reusing funds

        // no revert on failure

        uint balanceAfter = address(this).balance;
        require(balanceAfter == balanceBefore - SubX || balanceAfter == balanceBefore, "balance mismatch");
    }
}

